class Solution:
    def findMin(self, nums: List[int]) -> int:
        lo, hi = 0, len(nums) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] > nums[hi]:             # the minimum is to the right of mid
                lo = mid + 1
            else:                                # mid could be the minimum
                hi = mid
        return nums[lo]
